{
  "title": "The Glass Diver's Rescue",
  "gate_token": "NpSkWaAy8j5tK77EnwcbNA",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies a ruined map of the royal city.",
      "visual_description": "A cracked stone courtyard, overgrown with weeds, where Mara unrolls a torn parchment map, her brass compass glinting in the dim twilight.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver arrives through a shattered window.",
      "visual_description": "A broken stained-glass window in an abandoned hall; shards of colored glass rain down as the Glass Diver steps through, helmet reflecting fractured light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "Oracle Lamp warns of the castle gates' curse.",
      "visual_description": "A narrow alley with flickering shadows; the Oracle Lamp sits on a crate, its single eye glowing as it speaks urgently to Mara and the Glass Diver.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The Sleeping Tax Collector dozes on a ledger stack.",
      "visual_description": "A dusty chamber with cobwebbed ledgers; the Sleeping Tax Collector snores with his head on a ledger, stamped papers stuck to his sleeves like forgotten duties.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "Tin Fox scouts ahead past old royal banners.",
      "visual_description": "A long corridor hung with faded red and gold banners, tattered and dusty; Tin Fox moves silently, key-wind tail ticking, blue eyes scanning for danger.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara and the Glass Diver follow Tin Fox's trail.",
      "visual_description": "The corridor opens into a vast hall with cracked marble floors; Mara traces a compass bearing while the Glass Diver peers through a mirror shard on the wall.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Oracle Lamp reveals a cursed tower ahead.",
      "visual_description": "At a crossroads, the Oracle Lamp's flame turns blue, casting eerie light on a spiral staircase leading up into darkness; its voice trembles with warning.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The group ascends the cursed tower stairs.",
      "visual_description": "Narrow stone steps wind upward, each one engraved with shifting runes; the Glass Diver's helmet reflects ghostly figures that vanish when looked at directly.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Sleeping Tax Collector is found in a top room.",
      "visual_description": "A circular room at the tower's peak, filled with stacked tax rolls; the Sleeping Tax Collector naps on a pile of ancient ledgers, oblivious to the party's arrival.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Mara convinces the collector to share a secret.",
      "visual_description": "Mara shakes the collector awake; he blinks and fumbles, then points a sleepy finger at a hidden panel in the floor, marked with an old tax seal.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The group descends into underground tunnels.",
      "visual_description": "Beneath the panel, a ladder leads down into damp tunnels lit by phosphorescent moss; Tin Fox's eyes glow as it takes the lead.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "Oracle Lamp warns of armored patrols above.",
      "visual_description": "In the tunnel, the Oracle Lamp's flame dims and whispers that metallic footsteps echo on the stone ceiling above—patrols marching.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "The party reaches a magic door.",
      "visual_description": "The tunnel ends at a massive stone door covered in glowing runes that pulse in rhythm; Mara checks her compass while the Glass Diver studies the runes.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox solves the door's riddle.",
      "visual_description": "Tin Fox taps a sequence of runes with its metal paw, each press causing a chime; the door groans and swings open, revealing a torchlit chamber beyond.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The chamber holds the rescued captive.",
      "visual_description": "A circular chamber with a central pedestal, where a bound figure (not named, not visible as a generic) is freed by Mara; the Glass Diver cuts the ropes.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The alarm is raised as they flee.",
      "visual_description": "Behind them, the magic door seals shut with a boom; distant shouts and clanking metal echo from the tunnels as the party runs toward a light ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The escape leads to a bridge over a chasm.",
      "visual_description": "The tunnel opens onto a narrow stone bridge spanning a deep chasm; mist swirls below, and the bridge sways as the party hurries across.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The party crosses the bridge to safety.",
      "visual_description": "The bridge ends at a cliffside path; the group steps onto solid ground as the bridge crumbles behind them, the ruined city now distant in the smoky dawn.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

